  if (S.lastFrame === null) S.lastFrame = ts;
  const dt = Math.min(0.25, (ts - S.lastFrame) / 1000);
  S.lastFrame = ts; S.frameDt = dt;
  if (!S.paused) S.simTime += dt * S.speed;
